<script setup>





import {ref, watch, computed, defineAsyncComponent} from 'vue'
const ExtensionGuide=defineAsyncComponent(()=>import('./ExtensionGuide.vue'))
const section=ref('installed')

import {toast} from '../shared/composables/toast.js'
const props=defineProps({show:Boolean,embedded:Boolean});const emit=defineEmits(['close','state'])
const plugins=ref([]),current=ref(null),draft=ref({}),busy=ref(false)
const original=ref('');const dirty=computed(()=>!!current.value&&JSON.stringify(draft.value)!==original.value)
watch([dirty,busy],()=>emit('state',{dirty:dirty.value,busy:busy.value}),{immediate:true})
const labels={installed:'已安装',starting:'启动中',running:'已启用',stopping:'停止中',stopped:'已停用',error:'启动失败'}
async function api(path,opt){const r=await fetch('/api/extensions'+path,opt),body=await r.json().catch(()=>({}));if(!r.ok)throw new Error(body.error||'插件操作失败');return body}
async function select(v,force=false){if(!v||busy.value&&!force)return;if(!force&&dirty.value&&!await confirmAction('放弃当前未保存的插件配置？'))return;current.value=v;draft.value=Object.fromEntries(v.manifest.configuration.map(f=>[f.key,f.type==='secret'?'':f.type==='json'?v.config?.[f.key]===undefined?'':JSON.stringify(v.config[f.key],null,2):v.config?.[f.key]||'']));original.value=JSON.stringify(draft.value)}
async function load(){plugins.value=await api('');if(current.value){const next=plugins.value.find(v=>v.manifest.id===current.value.manifest.id);if(next)select(next,true);else current.value=null}}
watch(()=>props.show,async v=>{if(v&&!dirty.value&&!busy.value){try{await load()}catch(e){toast(e.message,'error')}}},{immediate:true})
async function action(fn,success){busy.value=true;try{await fn();await load();toast(success,'success')}catch(e){toast(e.message,'error')}finally{busy.value=false}}
async function close(){if(busy.value)return;if(dirty.value&&!await confirmAction('放弃当前未保存的插件配置？'))return;emit('close')}
function install(file){if(!file||busy.value)return false;if(file.size>64*1024*1024){toast('安装包最多 64 MiB','error');return false}const data=new FormData();data.append('package',file);action(async()=>{const v=await api('',{method:'POST',body:data});current.value=v},'插件已安装；配置并启用后才会连接外部系统');return false}
function save(){let data={};try{for(const f of current.value.manifest.configuration){const text=draft.value[f.key];if(f.type==='json'){if(text.trim())data[f.key]=JSON.parse(text)}else data[f.key]=text}}catch{toast('JSON 配置格式错误，请核对括号和引号','error');return}action(()=>api('/'+current.value.manifest.id+'/config',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),'配置已保存')}
function command(op){action(()=>api('/'+current.value.manifest.id+'/'+op,{method:'POST'}),{enable:'插件已启用',disable:'插件已停用，在途调用已取消',test:'插件验证成功；尚未执行业务操作'}[op])}
async function remove(){if(!await confirmAction('卸载该插件并删除其私有配置？外部系统数据不会修改。'))return;action(()=>api('/'+current.value.manifest.id,{method:'DELETE'}),'插件已卸载')}

import {confirmAction} from '../shared/shadcnFeedback.js'



import {Button,Dialog,DialogContent,DialogDescription,DialogHeader,DialogTitle,Empty,EmptyContent,EmptyDescription,EmptyHeader,Field,FieldLabel,Input,SidebarMenu,SidebarMenuButton,SidebarMenuItem,Spinner,Textarea} from '../shared/shadcn-ui.js'
</script>
<template><Dialog :open="embedded||show" @update:open="v=>{if(!v)close()}"><component :is="embedded?'section':DialogContent" :class="embedded?'min-w-0':'flex max-h-[92dvh] flex-col overflow-auto sm:max-w-[min(1200px,92vw)]'" :show-close-button="!busy" @escape-key-down="e=>{if(busy)e.preventDefault()}" @interact-outside="e=>{if(busy)e.preventDefault()}"><DialogHeader v-if="!embedded"><DialogTitle>插件管理</DialogTitle><DialogDescription class="sr-only">管理平台扩展插件</DialogDescription></DialogHeader><div class="extension-toolbar"><Button :aria-pressed="section==='installed'" @click="section='installed'" :variant="({primary:'default',secondary:'outline',text:'ghost',outline:'outline',dashed:'outline'})['secondary']||'outline'" :size="({small:'sm',mini:'xs',large:'lg',medium:'default'})['default']||'default'" :type="'button'" :disabled="(busy)">已安装插件</Button><Button :aria-pressed="section==='guide'" @click="section='guide'" :variant="({primary:'default',secondary:'outline',text:'ghost',outline:'outline',dashed:'outline'})['secondary']||'outline'" :size="({small:'sm',mini:'xs',large:'lg',medium:'default'})['default']||'default'" :type="'button'" :disabled="(busy)">开发规范与示例</Button></div><ExtensionGuide v-if="section==='guide'"/><div v-show="section==='installed'"><div class="extension-toolbar"><div class="inline-flex min-w-0 items-center gap-2"><Input type="file" aria-label="选择上传文件" class="max-w-xs" accept=".zip" :disabled="busy" @change="e=>{for(const file of e.target.files||[])(install)(file);e.target.value=''}"/></div><Button @click="action(load,'插件状态已刷新')" :variant="({primary:'default',secondary:'outline',text:'ghost',outline:'outline',dashed:'outline'})['secondary']||'outline'" :size="({small:'sm',mini:'xs',large:'lg',medium:'default'})['default']||'default'" :type="'button'" :disabled="(busy||dirty)">刷新</Button><span>外部能力插件 · 协议 v1</span></div><div class="extension-layout"><SidebarMenu aria-label="已安装的能力插件"><SidebarMenuItem v-for="v in plugins" :disabled="busy"><SidebarMenuButton class="h-10 text-sm" :is-active="(current?[current.manifest.id]:[]).includes(v.manifest.id)" @click="(key=>select(plugins.find(v=>v.manifest.id===key)))(v.manifest.id)"><span class="flex min-w-0 flex-col items-start gap-0.5"><b class="max-w-full truncate">{{v.manifest.name}}</b><small class="text-xs">{{v.manifest.version}} · {{labels[v.state]||v.state}}</small></span></SidebarMenuButton></SidebarMenuItem><Empty v-if="!plugins.length"><EmptyHeader><EmptyDescription>{{"暂无外部能力插件"}}</EmptyDescription></EmptyHeader></Empty></SidebarMenu><section v-if="current"><div class="extension-heading"><h3>{{current.manifest.name}}</h3><span>{{labels[current.state]||current.state}}</span></div><p class="extension-capabilities">能力：{{current.manifest.capabilities.join('、')}}</p><form class="space-y-5" @submit.prevent="save"><Field v-for="f in current.manifest.configuration" :key="f.key"><FieldLabel as="div">{{f.label}}{{f.required?' *':''}}</FieldLabel><Textarea v-if="f.type==='json'" v-model="draft[f.key]" :disabled="busy||current.enabled||current.state==='running'" placeholder="输入合法 JSON，格式见安装包 README" :rows="({minRows:(4),maxRows:Math.max((4),16)}).minRows||4"/><Input v-else v-model="draft[f.key]" :type="f.type==='secret'?'password':'text'" :disabled="busy||current.enabled||current.state==='running'" :placeholder="f.type==='secret'&&current.configured_secrets?.includes(f.key)?'已配置，留空保留原值':''" v-bind="{&quot;autocomplete&quot;:(f.type==='secret'?'new-password':'off')}"/></Field><div class="extension-actions"><Button :variant="({primary:'default',secondary:'outline',text:'ghost',outline:'outline',dashed:'outline'})['secondary']||'outline'" :size="({small:'sm',mini:'xs',large:'lg',medium:'default'})['default']||'default'" :type="&quot;submit&quot;" :disabled="(busy||current.enabled||current.state==='running')">保存配置</Button><Button v-if="current.state!=='running'" @click="command('enable')" :variant="({primary:'default',secondary:'outline',text:'ghost',outline:'outline',dashed:'outline'})[&quot;primary&quot;]||'outline'" :size="({small:'sm',mini:'xs',large:'lg',medium:'default'})['default']||'default'" :type="'button'" :disabled="(dirty)||(busy)"><Spinner v-if="busy"/>启用</Button><Button v-if="current.state==='running'" @click="command('test')" :variant="({primary:'default',secondary:'outline',text:'ghost',outline:'outline',dashed:'outline'})['secondary']||'outline'" :size="({small:'sm',mini:'xs',large:'lg',medium:'default'})['default']||'default'" :type="'button'" :disabled="(busy)"><Spinner v-if="busy"/>测试连接</Button><Button v-if="current.enabled||current.state==='running'" @click="command('disable')" :variant="({primary:'default',secondary:'outline',text:'ghost',outline:'outline',dashed:'outline'})['secondary']||'outline'" :size="({small:'sm',mini:'xs',large:'lg',medium:'default'})['default']||'default'" :type="'button'" :disabled="(busy)">停用</Button><Button @click="remove" :variant="({primary:'default',secondary:'outline',text:'ghost',outline:'outline',dashed:'outline'})['secondary']||'outline'" :size="({small:'sm',mini:'xs',large:'lg',medium:'default'})['default']||'default'" :type="'button'" :disabled="(busy||current.enabled||current.state==='running')">卸载</Button></div></form><small>修改配置或更新版本请先停用。上传包会以平台账号运行，请仅安装受信任的插件。</small></section><p v-else-if="plugins.length">选择一个插件查看配置。</p></div></div></component></Dialog></template>
<style scoped>.extension-toolbar,.extension-heading,.extension-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.extension-toolbar{margin-bottom:16px}.extension-toolbar span,small,.extension-capabilities{color:var(--muted-foreground)}.extension-layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:20px}.extension-layout nav{display:grid;align-content:start;gap:8px}.extension-layout label{display:grid;gap:6px;margin:14px 0}.extension-layout section{min-width:0}.extension-actions{margin-bottom:12px}.extension-capabilities{overflow-wrap:anywhere;margin:8px 0 16px}@media(max-width:700px){.extension-layout{grid-template-columns:1fr}.extension-layout nav{grid-template-columns:repeat(auto-fit,minmax(160px,1fr))}}</style>
